//! The app icons' artwork, drawn here in code as flat shapes: a selection being dragged out on a
//! colour field, finished by a cursor for the capture service and by a pencil for the editor.
//! Every shape is a sum in this file, sampled at a point of the unit square. Nothing is traced,
//! copied or generated by an image model.
//!
//! The sizes up to 32 px draw the same picture with heavier lines and a bigger cursor or pencil,
//! so it still reads.

/// Red, green, blue and alpha, each from 0 to 1.
pub type Rgba = [f32; 4];

/// A point of the unit square.
type Point = (f32, f32);

pub fn rgb(hex: u32) -> Rgba {
    [((hex >> 16) & 255) as f32 / 255.0, ((hex >> 8) & 255) as f32 / 255.0, (hex & 255) as f32 / 255.0, 1.0]
}

const WHITE: u32 = 0xFF_FF_FF;
/// The coral of the cursor and the pencil, the same in both icons.
pub const CORAL: u32 = 0xFF_6A_4D;

/// The capture service's colours: a dark field and a teal selection.
const CAPTURE_TOP: u32 = 0x1D_2A_38;
pub const CAPTURE_BOTTOM: u32 = 0x0D_14_1C;
pub const TEAL: u32 = 0x2C_D6_BE;

/// The editor's colours: an indigo field and a pale selection.
const EDITOR_TOP: u32 = 0x6A_52_DB;
const EDITOR_BOTTOM: u32 = 0x2D_21_70;
const EDITOR_LINE: u32 = 0xE4_DE_FF;
const EDITOR_INK: u32 = 0x1E_16_50;

const PENCIL_WOOD: u32 = 0xF7_E7_C6;
const PENCIL_BAND: u32 = 0xF7_F3_FF;
const PENCIL_ERASER: u32 = 0xFF_B3_A6;

/// The selection: its near and far edges (it's square), line width, and handle half-width.
struct Selection {
    near: f32,
    far: f32,
    line: f32,
    handle: f32,
}

const SELECTION: Selection = Selection { near: 0.20, far: 0.72, line: 0.04, handle: 0.05 };
const SELECTION_SMALL: Selection = Selection { near: 0.15, far: 0.68, line: 0.075, handle: 0.08 };

/// An arrow cursor, its tip first, drawn at the corner of the selection that's being dragged.
const CURSOR: [Point; 7] = [(0.0, 0.0), (0.0, 0.35), (0.085, 0.265), (0.145, 0.385), (0.21, 0.355), (0.15, 0.235), (0.27, 0.235)];
/// How wide the dark edge round the cursor and the pencil is.
const OUTLINE: f32 = 0.03;

/// The pencil's half-width and where each part ends, along it from the tip.
const PENCIL_WIDTH: f32 = 0.085;
const PENCIL_LEAD: f32 = 0.05;
const PENCIL_POINT: f32 = 0.14;
const PENCIL_BODY: f32 = 0.33;
const PENCIL_BAND_END: f32 = 0.355;
const PENCIL_END: f32 = 0.44;

/// `top` over `base`, by `alpha`.
fn over(base: Rgba, top: Rgba, alpha: f32) -> Rgba {
    [base[0] + (top[0] - base[0]) * alpha, base[1] + (top[1] - base[1]) * alpha, base[2] + (top[2] - base[2]) * alpha, 1.0]
}

/// The field, lighter at the top left.
fn field(top: u32, bottom: u32, x: f32, y: f32) -> Rgba {
    over(rgb(top), rgb(bottom), (x + y) / 2.0)
}

/// Distance from a rounded rectangle's edge (negative inside); coordinates in the unit square.
pub fn round_rect(x: f32, y: f32, cx: f32, cy: f32, hw: f32, hh: f32, r: f32) -> f32 {
    let (dx, dy) = ((x - cx).abs() - (hw - r), (y - cy).abs() - (hh - r));
    dx.max(dy).min(0.0) + (dx.max(0.0).powi(2) + dy.max(0.0).powi(2)).sqrt() - r
}

/// Distance from a polygon's edge (negative inside).
fn polygon(points: &[Point], x: f32, y: f32) -> f32 {
    let mut nearest = f32::MAX;
    let mut inside = false;
    let mut last = points.last().copied().unwrap_or((0.0, 0.0));
    for &(px, py) in points {
        let (ex, ey) = (px - last.0, py - last.1);
        let (wx, wy) = (x - last.0, y - last.1);
        let t = ((wx * ex + wy * ey) / (ex * ex + ey * ey).max(f32::EPSILON)).clamp(0.0, 1.0);
        nearest = nearest.min((wx - ex * t).powi(2) + (wy - ey * t).powi(2));
        if (py > y) != (last.1 > y) && x < ex * (y - last.1) / ey + last.0 {
            inside = !inside;
        }
        last = (px, py);
    }
    if inside { -nearest.sqrt() } else { nearest.sqrt() }
}

/// The selection over `base`: a tinted square, its outline and three corner handles. The fourth
/// corner is the one the cursor or pencil holds.
fn selection(base: Rgba, line: u32, tint: f32, small: bool, x: f32, y: f32) -> Rgba {
    let s = if small { SELECTION_SMALL } else { SELECTION };
    let (mid, half) = ((s.near + s.far) / 2.0, (s.far - s.near) / 2.0);
    let edge = round_rect(x, y, mid, mid, half, half, 0.035);
    for (cx, cy) in [(s.near, s.near), (s.far, s.near), (s.near, s.far)] {
        if round_rect(x, y, cx, cy, s.handle, s.handle, s.handle * 0.36) < 0.0 {
            return rgb(WHITE);
        }
    }
    if edge.abs() < s.line / 2.0 {
        rgb(line)
    } else if edge < 0.0 {
        over(base, rgb(line), tint)
    } else {
        base
    }
}

/// The capture service's icon: a teal selection on a dark field, and a coral cursor.
pub fn capture(x: f32, y: f32, small: bool) -> Rgba {
    let base = selection(field(CAPTURE_TOP, CAPTURE_BOTTOM, x, y), TEAL, 0.27, small, x, y);
    let (tip, scale) = if small { (0.44, 1.32) } else { (0.58, 1.0) };
    let edge = polygon(&CURSOR, (x - tip) / scale, (y - tip) / scale);
    if edge < 0.0 {
        rgb(CORAL)
    } else if edge < OUTLINE {
        rgb(CAPTURE_BOTTOM)
    } else {
        base
    }
}

/// The editor's icon: a pale selection on an indigo field, and a coral pencil.
pub fn editor(x: f32, y: f32, small: bool) -> Rgba {
    let base = selection(field(EDITOR_TOP, EDITOR_BOTTOM, x, y), EDITOR_LINE, 0.16, small, x, y);
    let (tip, scale) = if small { (0.40, 1.2) } else { (0.50, 1.0) };
    // Along the pencil from its tip, and across it, down and right from the tip.
    let (dx, dy) = ((x - tip) / scale, (y - tip) / scale);
    let root = std::f32::consts::FRAC_1_SQRT_2;
    let (along, across) = ((dx + dy) * root, (dy - dx) * root);
    let shape = [(0.0, 0.0), (PENCIL_POINT, PENCIL_WIDTH), (PENCIL_END, PENCIL_WIDTH), (PENCIL_END, -PENCIL_WIDTH), (PENCIL_POINT, -PENCIL_WIDTH)];
    let edge = polygon(&shape, along, across);
    if edge >= OUTLINE {
        return base;
    }
    if edge >= 0.0 {
        return rgb(EDITOR_INK);
    }
    rgb(match along {
        a if a < PENCIL_LEAD => EDITOR_INK,
        a if a < PENCIL_POINT => PENCIL_WOOD,
        a if a < PENCIL_BODY => CORAL,
        a if a < PENCIL_BAND_END => PENCIL_BAND,
        _ => PENCIL_ERASER,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_polygon_knows_inside_from_outside() {
        let square = [(0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0)];
        assert!((polygon(&square, 0.5, 0.5) + 0.5).abs() < 1e-5);
        assert!((polygon(&square, 2.0, 0.5) - 1.0).abs() < 1e-5);
    }

    #[test]
    fn the_cursor_and_the_pencil_stay_inside_the_icon() {
        for scale in [1.0_f32, 1.32] {
            let tip = if scale > 1.0 { 0.44 } else { 0.58 };
            for (x, y) in CURSOR {
                assert!(tip + x * scale + OUTLINE * scale < 1.0 && tip + y * scale + OUTLINE * scale < 1.0);
            }
        }
        let reach = (PENCIL_END + PENCIL_WIDTH + OUTLINE) * std::f32::consts::FRAC_1_SQRT_2;
        assert!(0.50 + reach < 1.0, "{reach}");
        assert!(0.40 + reach * 1.2 < 1.0, "{reach}");
    }
}
